const BUILT_IN_MAP = new Map<string, PaymentMethodDef>(BUILT_IN_PAYMENT_METHODS.map((m) => [m.code, m]));

export const allPaymentMethods = ref<PaymentMethodDef[]>(BUILT_IN_PAYMENT_METHODS.map((m) => ({ ...m })));
export const loadedPaymentMethodsStoreId = ref<number | null>(null);
export const enabledPaymentMethods = computed<PaymentMethodDef[]>(() => {
    const active = allPaymentMethods.value.filter((m) => m.isEnabled);
    return active.length ? active : BUILT_IN_PAYMENT_METHODS.filter((m) => m.isEnabled);
});

export function applyStorePaymentMethods(storeId: number, rows: StorePaymentMethodRow[]): void {
    loadedPaymentMethodsStoreId.value = storeId;
    allPaymentMethods.value = rows.map((row) => {
        const base = BUILT_IN_MAP.get(row.code);
        return {
            id: row.id,
            code: row.code,
            label: row.label || base?.label || row.code,
            category: row.is_custom ? 'custom' : (base?.category || row.category || 'traditional'),
            bg: row.bg_color || base?.bg || '#ede9fe',
            fg: row.fg_color || base?.fg || '#4c1d95',
            svgPath: base?.svgPath || DEFAULT_CUSTOM_SVG_PATH,
            iconSvg: row.icon_svg || null,
            isCustom: Boolean(row.is_custom),
            isEnabled: Boolean(row.is_enabled),
            sortOrder: row.sort_order,
        };
    });
}

export async function loadStorePaymentMethods(storeId?: number | null, force = false): Promise<void> {
    if (!storeId) {
        loadedPaymentMethodsStoreId.value = null;
        allPaymentMethods.value = BUILT_IN_PAYMENT_METHODS.map((m) => ({ ...m }));
        return;
    }
    if (!force && loadedPaymentMethodsStoreId.value === storeId) return;
    try {
        const { data } = await api.get<{ store_id: number; methods: StorePaymentMethodRow[] }>(
            `/business/stores/${storeId}/payment-methods`,
        );
        if (Array.isArray(data?.methods) && data.methods.length) {
            applyStorePaymentMethods(storeId, data.methods);
        }
    } catch {
        // Keep built-in defaults if offline or unauthorized
    }
}

export function svgDataUri(svg: string | null | undefined, fgColor?: string): string | null {
    if (!svg || !svg.trim()) return null;
    let normalized = svg.trim();
    if (fgColor && normalized.includes('currentColor')) {
        normalized = normalized.replace(/currentColor/g, fgColor);
    }
    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(normalized)}`;
}

// Backwards-compatible exports
export const PAYMENT_METHODS = BUILT_IN_PAYMENT_METHODS;
export const PAYMENT_METHOD_LABELS: Record<string, string> = Object.fromEntries(
    BUILT_IN_PAYMENT_METHODS.map((m) => [m.code, m.label]),
);

export function paymentMethodLabel(code: string): string {
    const found = allPaymentMethods.value.find((m) => m.code === code) || BUILT_IN_MAP.get(code);
    return found?.label || code;
}

export function paymentMethodInfo(code: string): PaymentMethodDef {
    return (
        allPaymentMethods.value.find((m) => m.code === code) ||
        BUILT_IN_MAP.get(code) || {
            code,
            label: code,
            category: 'custom',
            bg: '#ede9fe',
            fg: '#4c1d95',
            svgPath: DEFAULT_CUSTOM_SVG_PATH,
            isEnabled: true,
        }
    );
}
